import { addComponent, entityExists, set } from 'bitecs';
import { describe, expect, it } from 'vitest';
import { BroadcastScore, Position, Projectile, Sprite } from '../../src/core/components.js';
import { createEntity, spawnEnemy, spawnPlayer, spawnXpGem } from '../../src/core/helpers.js';
import { collisionSystem } from '../../src/core/systems/collisionSystem.js';
import { damageSystem } from '../../src/core/systems/damageSystem.js';
import { createTestWorld } from '../helpers/world-factory.js';

describe('damageSystem', () => {
  it('reduces enemy health when a projectile hits', () => {
    const world = createTestWorld();
    const projectile = createEntity(world);
    const enemy = spawnEnemy(world, 8, 0, 25);

    addComponent(world.ecs, projectile, set(Position, { x: 0, y: 0 }));
    addComponent(world.ecs, projectile, set(Sprite, { textureId: 0, width: 8, height: 8 }));
    addComponent(world.ecs, projectile, Projectile);

    damageSystem(world, collisionSystem(world));

    expect(world.stores.health.current[enemy]).toBe(15);
  });

  it('reduces player health when an enemy hits', () => {
    const world = createTestWorld();
    const player = spawnPlayer(world, 0, 0);

    spawnEnemy(world, 8, 0, 25);
    damageSystem(world, collisionSystem(world));

    expect(world.stores.health.current[player]).toBe(95);
  });

  it('xp gem collection is handled by itemPickupSystem (not damageSystem)', () => {
    const world = createTestWorld();
    const player = spawnPlayer(world, 0, 0);
    const gem = spawnXpGem(world, 4, 0, 7);

    addComponent(world.ecs, player, set(BroadcastScore, { current: 0 }));

    // damageSystem no longer handles XP gem collection — it's in itemPickupSystem
    damageSystem(world, collisionSystem(world));

    // Gem should still exist (damageSystem doesn't pick it up anymore)
    expect(entityExists(world.ecs, gem)).toBe(true);
  });

  it('destroys projectiles after they hit enemies', () => {
    const world = createTestWorld();
    const projectile = createEntity(world);

    spawnEnemy(world, 8, 0, 25);
    addComponent(world.ecs, projectile, set(Position, { x: 0, y: 0 }));
    addComponent(world.ecs, projectile, set(Sprite, { textureId: 0, width: 8, height: 8 }));
    addComponent(world.ecs, projectile, Projectile);

    damageSystem(world, collisionSystem(world));

    expect(entityExists(world.ecs, projectile)).toBe(false);
  });

  it('emits a hit combat event when a projectile damages an enemy', () => {
    const world = createTestWorld();
    const projectile = createEntity(world);
    spawnEnemy(world, 8, 0, 25);

    addComponent(world.ecs, projectile, set(Position, { x: 0, y: 0 }));
    addComponent(world.ecs, projectile, set(Sprite, { textureId: 0, width: 8, height: 8 }));
    addComponent(world.ecs, projectile, Projectile);

    damageSystem(world, collisionSystem(world));

    expect(world.combatEvents).toHaveLength(1);
    expect(world.combatEvents[0]).toMatchObject({
      type: 'hit',
      amount: 10,
      targetType: 'enemy',
    });
  });

  it('emits a hit combat event when an enemy damages the player', () => {
    const world = createTestWorld();
    spawnPlayer(world, 0, 0);
    spawnEnemy(world, 8, 0, 25);

    damageSystem(world, collisionSystem(world));

    expect(world.combatEvents).toHaveLength(1);
    expect(world.combatEvents[0]).toMatchObject({
      type: 'hit',
      targetType: 'player',
    });
    expect(world.combatEvents[0]!.amount).toBeGreaterThan(0);
  });

  it('emits a blocked combat event when player is invincible', () => {
    const world = createTestWorld();
    spawnPlayer(world, 0, 0);
    spawnEnemy(world, 8, 0, 25);

    // First hit applies damage
    damageSystem(world, collisionSystem(world));
    world.combatEvents.length = 0;

    // Second hit within invincibility window should be blocked
    world.elapsedMs += 100; // less than 250ms invincibility
    damageSystem(world, collisionSystem(world));

    expect(world.combatEvents).toHaveLength(1);
    expect(world.combatEvents[0]).toMatchObject({
      type: 'blocked',
      amount: 0,
      targetType: 'player',
    });
  });
});

tests/ecs/drop-system.test.ts.source:
import { query, setComponent } from 'bitecs';
import { describe, expect, it } from 'vitest';
import { DeathTimer, Enemy, Gold, Health, Position, XpGem } from '../../src/core/components.js';
import { spawnEnemy } from '../../src/core/helpers.js';
import { dropSystem } from '../../src/core/systems/dropSystem.js';
import { createTestWorld } from '../helpers/world-factory.js';

describe('dropSystem', () => {
  it('spawns loot when an enemy dies', () => {
    const world = createTestWorld();
    spawnEnemy(world, 100, 200, 10);

    // Kill the enemy
    const enemies = query(world.ecs, [Enemy]);
    const eid = enemies[0] as number;
    setComponent(world.ecs, eid, Health, { current: 0, max: 10 });

    dropSystem(world);

    // BASIC_MELEE table always drops XP (chance 1.0)
    const gems = query(world.ecs, [XpGem, Position]);
    expect(gems.length).toBeGreaterThanOrEqual(1);
  });

  it('emits a death combat event', () => {
    const world = createTestWorld();
    spawnEnemy(world, 50, 60, 10);

    const enemies = query(world.ecs, [Enemy]);
    const eid = enemies[0] as number;
    setComponent(world.ecs, eid, Health, { current: 0, max: 10 });

    dropSystem(world);

    const deathEvents = world.combatEvents.filter((e) => e.type === 'death');
    expect(deathEvents.length).toBe(1);
    expect(deathEvents[0]!.x).toBe(50);
    expect(deathEvents[0]!.y).toBe(60);
    expect(deathEvents[0]!.overkill).toBe(0);
    expect(deathEvents[0]!.targetType).toBe('enemy');
  });

  it('does not double-process the same entity', () => {
    const world = createTestWorld();
    spawnEnemy(world, 100, 200, 10);

    const enemies = query(world.ecs, [Enemy]);
    const eid = enemies[0] as number;
    setComponent(world.ecs, eid, Health, { current: 0, max: 10 });

    dropSystem(world);
    const firstCount = world.combatEvents.filter((e) => e.type === 'death').length;

    dropSystem(world);
    const secondCount = world.combatEvents.filter((e) => e.type === 'death').length;

    expect(secondCount).toBe(firstCount);
  });

  it('does not spawn drops for living enemies', () => {
    const world = createTestWorld();
    spawnEnemy(world, 100, 200, 10);

    dropSystem(world);

    const gems = query(world.ecs, [XpGem]);
    const golds = query(world.ecs, [Gold]);
    expect(gems.length).toBe(0);
    expect(golds.length).toBe(0);
    expect(world.combatEvents.filter((e) => e.type === 'death').length).toBe(0);
  });

  it('uses deterministic drops with seeded RNG', () => {
    function runDrop(seed: number) {
      const world = createTestWorld({ seed });
      spawnEnemy(world, 100, 200, 10);
      const enemies = query(world.ecs, [Enemy]);
      setComponent(world.ecs, enemies[0] as number, Health, { current: 0, max: 10 });
      dropSystem(world);
      return {
        gems: query(world.ecs, [XpGem]).length,
        golds: query(world.ecs, [Gold]).length,
        events: world.combatEvents.length,
      };
    }

    const run1 = runDrop(42);
    const run2 = runDrop(42);
    expect(run1).toEqual(run2);
  });

  it('can suppress loot while preserving death linger timing', () => {
    const world = createTestWorld();
    spawnEnemy(world, 100, 200, 10);

    const enemies = query(world.ecs, [Enemy]);
    const eid = enemies[0] as number;
    setComponent(world.ecs, eid, Health, { current: 0, max: 10 });

    dropSystem(world, { spawnLoot: false, deathLingerMs: 900 });

    expect(query(world.ecs, [XpGem]).length).toBe(0);
    expect(query(world.ecs, [Gold]).length).toBe(0);
    expect(world.stores.deathTimer.remainingMs[eid]).toBe(900);
    expect(query(world.ecs, [DeathTimer])).toContain(eid);
    expect(world.combatEvents.filter((event) => event.type === 'death')).toHaveLength(1);
  });
});

