import { entityExists, hasComponent, query, setComponent } from 'bitecs';
import { describe, expect, it } from 'vitest';
import { Health, Player, Position, XpGem } from '../../src/core/components.js';
import { spawnEnemy, spawnPlayer } from '../../src/core/helpers.js';
import { healthSystem } from '../../src/core/systems/healthSystem.js';
import { dropSystem } from '../../src/core/systems/dropSystem.js';
import { deathTimerSystem } from '../../src/core/systems/deathTimerSystem.js';
import { createTestWorld } from '../helpers/world-factory.js';

describe('healthSystem', () => {
  it('keeps entities with health above zero', () => {
    const world = createTestWorld();
    const eid = spawnEnemy(world, 100, 200, 25);

    healthSystem(world);

    expect(entityExists(world.ecs, eid)).toBe(true);
    expect(world.state).toBe('playing');
  });

  it('removes entities with health at or below zero (after death timer expires)', () => {
    const world = createTestWorld();
    const eid = spawnEnemy(world, 100, 200, 25);

    setComponent(world.ecs, eid, Health, { current: 0, max: 25 });
    dropSystem(world);
    healthSystem(world);

    // Entity has DeathTimer now — healthSystem skips it
    expect(entityExists(world.ecs, eid)).toBe(true);

    // Run deathTimerSystem enough frames to expire the 300ms timer (~18 frames at 16.67ms)
    for (let i = 0; i < 20; i++) {
      deathTimerSystem(world);
    }

    expect(entityExists(world.ecs, eid)).toBe(false);
  });

  it('sets game over for the player instead of removing it', () => {
    const world = createTestWorld();
    const eid = spawnPlayer(world, 100, 200);

    setComponent(world.ecs, eid, Health, { current: -1, max: 100 });
    healthSystem(world);

    expect(entityExists(world.ecs, eid)).toBe(true);
    expect(hasComponent(world.ecs, eid, Player)).toBe(true);
    expect(world.state).toBe('game_over');
  });

  it('drops loot at enemy death position via dropSystem', () => {
    const world = createTestWorld();
    const eid = spawnEnemy(world, 42, 77, 10);

    setComponent(world.ecs, eid, Health, { current: 0, max: 10 });
    dropSystem(world);
    healthSystem(world);

    // dropSystem spawns XP gems based on loot tables
    const gems = query(world.ecs, [XpGem, Position]);
    expect(gems.length).toBeGreaterThanOrEqual(1);
  });
});

tests/ecs/collision-system.test.ts.source:
import { addComponent, set, setComponent } from 'bitecs';
import { describe, expect, it } from 'vitest';
import { Position, Projectile, Sprite } from '../../src/core/components.js';
import { createEntity, spawnEnemy, spawnPlayer } from '../../src/core/helpers.js';
import { collisionSystem } from '../../src/core/systems/collisionSystem.js';
import { createTestWorld } from '../helpers/world-factory.js';

describe('collisionSystem', () => {
  it('detects player-enemy collisions', () => {
    const world = createTestWorld();
    const player = spawnPlayer(world, 0, 0);
    const enemy = spawnEnemy(world, 8, 0, 25);

    const result = collisionSystem(world);

    expect(result.pairs).toContainEqual({ a: Math.min(player, enemy), b: Math.max(player, enemy) });
  });

  it('detects projectile-enemy collisions', () => {
    const world = createTestWorld();
    const projectile = createEntity(world);
    const enemy = spawnEnemy(world, 8, 0, 25);

    addComponent(world.ecs, projectile, set(Position, { x: 0, y: 0 }));
    addComponent(world.ecs, projectile, set(Sprite, { textureId: 0, width: 8, height: 8 }));
    addComponent(world.ecs, projectile, Projectile);

    const result = collisionSystem(world);

    expect(result.pairs).toContainEqual({
      a: Math.min(projectile, enemy),
      b: Math.max(projectile, enemy),
    });
  });

  it('returns no collisions when entities do not overlap', () => {
    const world = createTestWorld();

    spawnPlayer(world, 0, 0);
    spawnEnemy(world, 256, 256, 25);

    expect(collisionSystem(world).pairs).toEqual([]);
  });

  it('rebuilds the grid each frame as entities move', () => {
    const world = createTestWorld();
    const player = spawnPlayer(world, 0, 0);
    const enemy = spawnEnemy(world, 200, 0, 25);

    expect(collisionSystem(world).pairs).toEqual([]);

    setComponent(world.ecs, enemy, Position, { x: 8, y: 0 });
    const updatedResult = collisionSystem(world);

    expect(updatedResult.pairs).toContainEqual({
      a: Math.min(player, enemy),
      b: Math.max(player, enemy),
    });
  });
});

